def read(n):return json.loads((_repo_path(ROOT, n)).read_text())
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for c in iter(lambda:f.read(2**20),b''):h.update(c)
 return h.hexdigest()
def write(p,x):
 with p.open('x') as f:json.dump(x,f,indent=2,ensure_ascii=False,allow_nan=False)
def resolve(d,path):
 for k in path:d=d[k]
 return d
